CREATE TABLE notizia (
  id int NOT NULL,
  titolo varchar(100) NOT NULL,
  contenuto text,
  data_pubblicazione date DEFAULT NULL,
  link_immagine varchar(255) DEFAULT NULL,
  squadra_coinvolta varchar(200) DEFAULT NULL,
  PRIMARY KEY (id)
) 

INSERT INTO notizia VALUES (1,'Lotta scudetto riaperta dopo il calo dell’Inter','La corsa allo scudetto in Serie A si riapre clamorosamente dopo alcune settimane difficili per l’Inter. La squadra nerazzurra, che fino a poche giornate fa sembrava avere il controllo del campionato, ha rallentato il proprio cammino con una sconfitta pesante nel derby e due pareggi consecutivi che hanno ridotto sensibilmente il vantaggio in classifica. A beneficiarne sono state soprattutto Milan e Napoli, che hanno saputo approfittare del momento negativo dei rivali accorciando le distanze. Il calendario delle prossime giornate, con diversi scontri diretti, potrebbe risultare decisivo per determinare l’esito finale della stagione. L’equilibrio ritrovato rende il finale di campionato particolarmente incerto e spettacolare, con almeno tre squadre ancora pienamente in corsa per il titolo.','2026-04-02','https://milano.lamilano.it/wp-content/uploads/2026/03/Progetto-senza-titolo-1-2.jpg','FC Internazionale Milano, AC Milan, SSC Napoli'),(2,'Tensione al Napoli: Lukaku salta l’allenamento','Momenti di tensione in casa Napoli dopo l’assenza di Romelu Lukaku all’allenamento successivo alla pausa per le nazionali. L’attaccante belga non si è presentato al centro sportivo senza fornire spiegazioni immediate, generando preoccupazione e irritazione all’interno dello spogliatoio e della dirigenza. Il club sta valutando eventuali provvedimenti disciplinari, mentre lo staff tecnico cerca di mantenere la concentrazione del gruppo in un momento delicato della stagione. Lukaku, arrivato con grandi aspettative, non ha finora inciso come previsto e questa situazione rischia di complicare ulteriormente il suo rapporto con l’ambiente partenopeo. Nei prossimi giorni sono attesi chiarimenti ufficiali sia da parte del giocatore sia della società.','2026-04-02','https://dimages2.gazzettaobjects.it/files/image_528_298/files/fp/uploads/2026/03/31/69cb98161e666.r_d.1500-702-3078.jpeg','SSC Napoli'),(3,'Indagine sulla vendita di San Siro','La Procura di Milano ha avviato un’indagine sulla procedura di vendita dello stadio San Siro, che coinvolge i club di Milan e Inter e l’amministrazione comunale. Gli inquirenti stanno esaminando documenti e atti relativi alla cessione dell’impianto e alle modalità con cui è stata gestita l’operazione, ipotizzando possibili irregolarità amministrative. Nelle ultime ore sono state effettuate perquisizioni negli uffici del Comune, con l’obiettivo di raccogliere elementi utili all’inchiesta. Il progetto legato al futuro dello storico stadio rappresenta un passaggio fondamentale per lo sviluppo infrastrutturale delle due società milanesi, ma ora rischia di subire rallentamenti a causa degli sviluppi giudiziari. Le autorità hanno comunque sottolineato che le indagini sono ancora in fase preliminare.','2026-03-31','https://dimages2.gazzettaobjects.it/files/image_712_401/uploads/2025/09/30/68dc03ea16ebf.png','FC Internazionale Milano, AC Milan'),(4,'Juventus in ripresa: vittoria convincente in casa','La Juventus torna alla vittoria davanti ai propri tifosi con una prestazione solida e convincente. Dopo alcune settimane altalenanti, i bianconeri hanno mostrato segnali di crescita sia dal punto di vista del gioco che della mentalità. La squadra ha controllato il ritmo della partita fin dai primi minuti, riuscendo a concretizzare le occasioni create e limitando i rischi in difesa. L’allenatore ha sottolineato l’importanza di questa vittoria per il morale del gruppo, soprattutto in vista dei prossimi impegni decisivi per la corsa alle competizioni europee. La Juventus sembra aver ritrovato compattezza e fiducia nei propri mezzi.','2026-04-01','https://dimages2.gazzettaobjects.it/files/image_768_434/uploads/2025/12/10/6939f9c82c565.jpeg','Juventus FC'),(5,'Milan, difesa ritrovata: porta inviolata dopo settimane','Il Milan ritrova solidità difensiva e mantiene la porta inviolata dopo diverse giornate in cui aveva concesso troppo agli avversari. La squadra rossonera ha mostrato grande organizzazione nella fase difensiva, con una linea arretrata attenta e concentrata per tutta la durata dell’incontro. Questo risultato rappresenta un segnale importante per l’allenatore, che nelle ultime settimane aveva lavorato intensamente proprio sull’equilibrio tattico. Con una difesa più solida, il Milan può ora guardare con maggiore fiducia alle prossime sfide, fondamentali per restare agganciato alla lotta per il titolo.','2026-04-01','https://milanvibes.it/wp-content/uploads/2025/11/derby-inter-pavlovic-tomori-gabbia-860x573.jpg','AC Milan'),(6,'Roma, rimonta nel finale: tre punti fondamentali','La Roma conquista una vittoria preziosa grazie a una rimonta completata negli ultimi minuti di gioco. Dopo essere passata in svantaggio, la squadra giallorossa ha reagito con determinazione, aumentando la pressione offensiva e trovando il pareggio prima e il gol decisivo nel finale. L’Olimpico ha spinto la squadra fino all’ultimo minuto, premiando lo sforzo con un successo che potrebbe rivelarsi fondamentale nella corsa alle posizioni europee. L’allenatore ha elogiato il carattere dei suoi giocatori, sottolineando la capacità di non arrendersi anche nei momenti più difficili.','2026-03-31','https://www.raiplay.it/resizegd/434x-/dl/img/2025/12/15/1765835709188_Roma-Como-2048x1152.jpg','AS Roma'),(7,'Atalanta show: attacco devastante e goleada','Prestazione straordinaria dell’Atalanta, che domina la partita con un attacco esplosivo e mette a segno una goleada. La squadra bergamasca ha imposto il proprio gioco sin dai primi minuti, sfruttando la velocità e la qualità tecnica dei suoi attaccanti. Il risultato finale rispecchia pienamente l’andamento della gara, con gli avversari mai realmente in grado di contrastare la superiorità nerazzurra. Questo successo rafforza la posizione dell’Atalanta nelle zone alte della classifica e conferma la pericolosità offensiva della squadra.','2026-03-31','https://cdn.bergamonews.it/photogallery_new/images/2025/05/generico-maggio-2025-799439.jpg','Atalanta BC'),(8,'Lazio, occasione sprecata: solo un pareggio','La Lazio non riesce ad andare oltre il pareggio in una partita che sembrava alla portata. Nonostante un buon avvio e diverse occasioni create, la squadra biancoceleste non è riuscita a concretizzare le opportunità, subendo il ritorno degli avversari nella seconda parte della gara. Il risultato lascia l’amaro in bocca, soprattutto considerando l’importanza dei punti in palio per la corsa europea. L’allenatore ha evidenziato la necessità di maggiore cinismo sotto porta per evitare di perdere occasioni preziose.','2026-03-30','https://abitarearoma.it/wp/wp-content/uploads/2024/03/foto-lazio-sconfitta.jpeg','SS Lazio'),(9,'Fiorentina, giovani protagonisti nella vittoria','La Fiorentina conquista una vittoria importante grazie al contributo decisivo dei suoi giovani talenti. I ragazzi del vivaio hanno dimostrato personalità e qualità, risultando determinanti nei momenti chiave della partita. La società continua a puntare sullo sviluppo dei giovani, e questa scelta sembra dare i suoi frutti anche in termini di risultati. L’entusiasmo attorno alla squadra cresce, alimentato da prestazioni convincenti e da un progetto tecnico in continua evoluzione.','2026-03-29','https://laviola.s3.eu-south-1.wasabisys.com/posts/2025/11/gudmundsson-kean-546582.jpg','ACF Fiorentina'),(10,'Torino, difesa solida ma attacco sterile','Il Torino mostra una buona organizzazione difensiva ma fatica a trovare la via del gol. La squadra granata ha concesso poco agli avversari, dimostrando attenzione e disciplina nella fase difensiva, ma in avanti è mancata la precisione necessaria per concretizzare le occasioni create. Il risultato finale rispecchia queste difficoltà, con un pareggio che non soddisfa pienamente le ambizioni del club. Lo staff tecnico è al lavoro per migliorare la fase offensiva e rendere la squadra più incisiva.','2026-03-29','https://static.toronews.net/202512/19f575e51c58436858a5f0bbc1d866f9-1024x683.jpg','Torino FC');


